Q: How to map() a Stream until it is cancelled in Dart? A: <p>If you use <code>stream.where()</code>, this method will iterate through all your records.<br />
This is because it is a filter function.<br />
So, if you have 1000 records in your selection, they will all be processed by the <code>stream.where()</code> method.</p>
<p>Another way is to actually cancel your subscription.</p>
<pre class="lang-dart prettyprint-override"><code>import 'dart:async';

import 'package:multitasking/multitasking.dart';

Future&lt;void&gt; main() async {
  final cursor = Stream.periodic(Duration(milliseconds: 10), (value) {
    print('cursor: $value');
    return value;
  });

  final cts = CancellationTokenSource();
  final processed = StreamController&lt;int&gt;();
  unawaited(() async {
    try {
      await for (final event
          in cursor.asCancelable(cts.token, throwIfCanceled: false)) {
        processed.add(event);
        unawaited(_process(event));
      }
    } finally {
      await processed.close();
    }
  }());

  processed.stream.map((event) {
    return 'Mapped($event)';
  }).listen((event) {
    print('Processed: $event');
  });

  Timer(Duration(milliseconds: 50), () {
    print('User picked some value');
    cts.cancel();
  });
}

Future&lt;void&gt; _process(int value) async {
  print('_process($value)');
  await Future&lt;void&gt;.delayed(Duration(milliseconds: 15));
}

</code></pre>
